I18N.bn.goalPrivacy='লক্ষ্যটি এই স্থানীয় ডেটাবেসে সংরক্ষিত হয়।';
const COLORS=['#287f69','#7eb89a','#d9a34c','#7799b4','#987fb0','#c5796c','#6daaa8','#a6b56b','#cf9365','#8a9ca5','#b5a47d'];
const CATEGORIES=['Food','Transport','Shopping','Bills','Mobile Recharge','Education','Entertainment','Healthcare','Cash Out','Transfer','Other'];
let lang='en', personas=[], selectableProfiles=[], activePersona=null, summary=null, activeGoalId=null, activePlan=null, currentPage='overview', reductions={}, toastTimer, importReview=null, importColumns=null, personaLoadToken=0;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const tr=k=>(I18N[lang][k]??I18N.en[k]??k);
const money=n=>`৳ ${new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-BD',{maximumFractionDigits:0}).format(Number(n)||0)}`;
const number=n=>new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-US',{maximumFractionDigits:1}).format(Number(n)||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(msg,error=false){let t=$('#toast');t.textContent=msg;t.className='toast show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='toast',3600)}
async function api(path,options={}){let r=await fetch(API+path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let body;try{body=await r.json()}catch{throw Error('The server returned an unreadable response.')}if(!r.ok)throw Error(body.detail?.message||body.detail||tr('error'));return body.data}
function translateStatic(){document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>{let k=el.dataset.i18n;if(I18N[lang][k])el.textContent=I18N[lang][k]});$('#language-toggle').checked=lang==='bn';$('#language-toggle').setAttribute('aria-label',lang==='bn'?'Switch to English':'বাংলায় দেখুন');if(activePersona){$('#user-name').textContent=activePersona.name} }
function statusText(status){return status==='On Track'?tr('onTrack'):status==='Tight'?tr('tight'):status==='Needs Adjustment'?tr('needsAdjustment'):tr('difficult')}
function categoryText(s){const map={'Food':'food','Transport':'transport','Shopping':'shopping','Bills':'bills','Mobile Recharge':'mobileRecharge','Education':'education','Entertainment':'entertainment','Healthcare':'healthcare','Cash Out':'cashOut','Transfer':'transfer','Other':'other'};return tr(map[s]||s)}
async function loadPersonas(preferredId=null){personas=await api('/personas');let users=await api('/users');let imported=users.filter(u=>u.is_imported).map(u=>({persona_id:`import-${u.user_id}`,user_id:u.user_id,name:u.display_name||u.user_id,profile:`${tr('localImport')}${u.region&&u.region!=='Not provided'?` · ${u.region}`:''}`,goal:{name:'Emergency Fund',target_amount:60000,current_saved_amount:u.current_savings,target_months:6,priority:'medium'},is_imported:true}));selectableProfiles=[...personas,...imported];let sel=$('#persona-select');sel.innerHTML=selectableProfiles.map(p=>`<option value="${esc(p.persona_id)}">${esc(p.name)} · ${esc(p.profile)}</option>`).join('');renderPersonaCards();let initial=preferredId||personas[0]?.persona_id;if(initial)await selectPersona(initial)}
async function selectPersona(id){let p=selectableProfiles.find(x=>x.persona_id===id);if(!p)return;let requestId=++personaLoadToken;activePersona=p;$('#persona-select').value=id;$('#user-name').textContent=p.name;try{let nextSummary=await api(`/users/${encodeURIComponent(p.user_id)}/summary`);if(requestId!==personaLoadToken)return;summary=nextSummary;activeGoalId=summary.goals?.[0]?.goal_id||null;activePlan=summary.planning;renderOverview();fillGoalForm();if(currentPage==='plan'){if(activePlan?.goal_id)showPlan(activePlan);else renderEmptyPlan()}if(currentPage==='whatif')loadWhatIf();if(currentPage==='spending')renderSpending();if(currentPage==='transactions')loadTransactions()}catch(e){if(requestId===personaLoadToken)notify(e.message,true)}}
function fmtDate(s){if(!s)return'—';let d=new Date(s+'T12:00:00');return new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-GB',{day:'numeric',month:'short',year:'numeric'}).format(d)}
function renderProfileContext(){let imported=Boolean(activePersona?.is_imported),bn=lang==='bn';let copy=imported?{badge:bn?'স্থানীয় CSV':'LOCAL CSV',title:bn?'স্থানীয় CSV প্রোফাইল':'Local CSV profile',detail:bn?'লেনদেন এই ডিভাইসেই থাকে':'Transactions stay on this device',overview:bn?'আমদানি করা লেনদেন ও সঞ্চয়ের পথ একসঙ্গে দেখুন।':'A clear view of your imported transactions and savings path.',trend:bn?'আপনার আমদানি করা মাসিক খরচ':'Expenses from your imported monthly transactions',category:bn?'সর্বশেষ আমদানি করা মাসের লেনদেন':'Transactions from the latest imported month',spending:bn?'আমদানি করা লেনদেন ব্যবহারিক খাতে সাজানো হয়েছে।':'Your imported transactions grouped into practical categories.',latest:bn?'সর্বশেষ আমদানি করা মাস':'Latest imported month',history:bn?'আমদানি করা মাসভিত্তিক ইতিহাস':'Imported monthly history',ledger:bn?'আমদানি করা হিসাব':'IMPORTED LEDGER',transactions:bn?'খরচ বিশ্লেষণ ও পূর্বাভাসে ব্যবহৃত আমদানি করা তথ্য দেখুন।':'Review imported records used by spending analysis and forecasting.',disclaimer:bn?'পূর্বাভাস আপনার আমদানি করা ইতিহাস ব্যবহার করে; মডেলটি কৃত্রিম তথ্যে যাচাই করা হয়েছে। ফল নিশ্চিত নয়।':'Forecasts use your imported history, while the model was evaluated on synthetic data only. Estimates are not guarantees.'}:{badge:tr('demoData'),title:tr('syntheticOnly'),detail:tr('privacyMini'),overview:tr('overviewSub'),trend:tr('spendingTrendSub'),category:tr('categorySub'),spending:tr('spendingSub'),latest:tr('latestMonth'),history:tr('fullHistory'),ledger:tr('syntheticLedger'),transactions:tr('transactionsSub'),disclaimer:tr('estimateDisclaimer')};for(let [id,key] of [['profile-data-badge','badge'],['profile-data-title','title'],['profile-data-detail','detail'],['overview-context','overview'],['trend-context','trend'],['category-context','category'],['spending-context','spending'],['latest-month-context','latest'],['monthly-history-context','history'],['transaction-ledger-context','ledger'],['transactions-context','transactions'],['estimate-disclaimer','disclaimer']]){let node=$(`#${id}`);if(node)node.textContent=copy[key]}}
function updateForecastRangeNote(){
  let node=$('#forecast-range-note');
  if(!node||!summary)return;
  let forecast=summary.planning?.forecast||{},range=forecast.estimate_range;
  if(!forecast.available){node.textContent=lang==='bn'?'পূর্বাভাসের জন্য পর্যাপ্ত লেনদেনের ইতিহাস নেই।':'There is not enough transaction history for a forecast.';return}
  if(!range){node.textContent=lang==='bn'?'এই মডেল ফাইলে ত্রুটির পরিসর নেই। বর্তমান প্রশিক্ষণ পদ্ধতিতে মডেল আবার train করুন।':'This saved model has no empirical error range. Retrain it with the current training pipeline to generate one.';return}
  let low=money(range.lower),high=money(range.upper);
  if(forecast.data_origin==='user_import')node.textContent=lang==='bn'?'সাম্প্রতিক আমদানি করা মাসের খরচ: '+low+'–'+high+'। এটি অতীতের ওঠানামা, ভবিষ্যতের নিশ্চয়তা নয়।':'Recent imported-month range: '+low+'–'+high+'. This describes past variation, not a forecast guarantee.';
  else if(range.kind==='model_validation')node.textContent=lang==='bn'?'কৃত্রিম তথ্যের যাচাইভিত্তিক অভিজ্ঞতালব্ধ পরিসর: '+low+'–'+high+'। এটি সম্ভাব্যতার নিশ্চয়তাপূর্ণ সীমা নয়।':'Empirical range from synthetic validation: '+low+'–'+high+'. This is not a calibrated probability interval.';
  else node.textContent=lang==='bn'?'সাম্প্রতিক কৃত্রিম মাসের খরচ: '+low+'–'+high+'। এটি অতীতের তথ্য, পূর্বাভাসের সীমা নয়।':'Recent synthetic-month range: '+low+'–'+high+'. This describes history, not a prediction interval.';
}
function renderOverview(){if(!summary)return;renderProfileContext();let p=summary.planning,s=summary.spending;$('#user-name').textContent=activePersona.name;$('#kpi-savings').textContent=money(summary.current_savings);$('#kpi-savings-note').textContent=activePersona.profile;$('#kpi-income').textContent=money(summary.monthly_income_estimate);$('#kpi-spending').textContent=money(summary.monthly_spending);$('#kpi-spending-note').textContent=`${number(summary.transaction_count)} ${lang==='bn'?'লেনদেন':'transactions'} · ${summary.latest_month||''}`;$('#kpi-capacity').textContent=money(p.feasible_monthly_savings);$('#status-label').textContent=statusText(p.planning_status);$('#status-reason').textContent=lang==='bn'?p.status_reason_bn:p.status_reason_en;let pill=$('#status-pill');pill.textContent=statusText(p.planning_status);pill.className='pill '+(p.planning_status==='Tight'?'tight':p.planning_status==='Needs Adjustment'?'adjust':p.planning_status.startsWith('Difficult')?'difficult':'');$('#goal-title').textContent=p.goal_name;$('#progress-pct').textContent=`${number(p.progress_pct)}%`;$('#progress-bar').style.width=`${p.progress_pct}%`;$('#progress-current').textContent=money(p.current_saved_amount);$('#progress-target').textContent=money(p.target_amount);$('#goal-required').textContent=money(p.required_monthly_savings);$('#goal-completion').textContent=p.expected_completion_months===null?tr('noEstimate'):`${number(p.expected_completion_months)} ${tr('monthsLabel')}`;$('#overview-explanation').textContent=lang==='bn'?p.explanation_bn:p.explanation_en;updateForecastRangeNote();drawTrend($('#trend-chart'),s.monthly||[]);drawDonut($('#category-chart'),s.monthly?.at(-1)?.categories||{},$('#category-legend'));translateStatus()}
function translateStatus(){/* status wording is re-rendered from the grounded API status */if(summary){let p=summary.planning;$('#status-label').textContent=statusText(p.planning_status);$('#status-pill').textContent=statusText(p.planning_status);$('#status-reason').textContent=lang==='bn'?p.status_reason_bn:p.status_reason_en;$('#overview-explanation').textContent=lang==='bn'?p.explanation_bn:p.explanation_en}}
function canvasCtx(canvas){let rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);let ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);return{ctx,w:rect.width,h:rect.height}}
function drawTrend(canvas,rows){if(!canvas)return;let{ctx,w,h}=canvasCtx(canvas),summaryNode=$('#trend-summary');ctx.clearRect(0,0,w,h);let arr=(rows||[]).slice(-8);if(!arr.length){if(summaryNode)summaryNode.textContent=tr('noChartData');ctx.fillStyle='#899b93';ctx.textAlign='center';ctx.font='10px DM Sans';ctx.fillText(tr('noChartData'),w/2,h/2);return}let vals=arr.map(x=>Math.max(0,Number(x.total)||0)),max=Math.max(...vals,1)*1.18,min=0,pad={l:47,r:9,t:12,b:25};ctx.font='9px DM Sans, sans-serif';ctx.strokeStyle='#edf2ef';ctx.fillStyle='#81928a';ctx.lineWidth=1;for(let i=0;i<4;i++){let value=max*(1-i/3),y=pad.t+(h-pad.t-pad.b)*i/3;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillText(new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-BD',{notation:'compact',maximumFractionDigits:1}).format(value),pad.l-6,y)}let pts=vals.map((v,i)=>({x:pad.l+i*(w-pad.l-pad.r)/Math.max(1,vals.length-1),y:pad.t+(max-v)/(max-min)*(h-pad.t-pad.b)}));ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineTo(pts.at(-1).x,h-pad.b);ctx.lineTo(pts[0].x,h-pad.b);ctx.closePath();let g=ctx.createLinearGradient(0,pad.t,0,h);g.addColorStop(0,'#8fc6a64c');g.addColorStop(1,'#8fc6a600');ctx.fillStyle=g;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#3e9a77';ctx.lineWidth=2;ctx.stroke();pts.forEach((p,i)=>{ctx.beginPath();ctx.arc(p.x,p.y,2.8,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#398e70';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#7a8f86';ctx.font='8px DM Sans';ctx.textAlign='center';ctx.textBaseline='alphabetic';let date=new Date(`${arr[i].month}-01T12:00:00`);ctx.fillText(new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-US',{month:'short'}).format(date),p.x,h-7)});ctx.textAlign='left';if(summaryNode)summaryNode.textContent=`${tr('chartRange')} ${arr[0].month}–${arr.at(-1).month}. ${tr('chartLatest')} ${money(vals.at(-1))}.`}
function drawDonut(canvas,categories,legendEl){if(!canvas)return;let entries=Object.entries(categories).filter(x=>Number(x[1])>0).sort((a,b)=>b[1]-a[1]).slice(0,7),{ctx,w,h}=canvasCtx(canvas);ctx.clearRect(0,0,w,h);if(!entries.length){ctx.beginPath();ctx.arc(w/2,h/2,55,0,Math.PI*2);ctx.strokeStyle='#e9efeb';ctx.lineWidth=18;ctx.stroke();if(legendEl)legendEl.innerHTML=`<span class="legend-row">${esc(tr('noTransactions'))}</span>`;return}let total=entries.reduce((a,x)=>a+x[1],0),start=-Math.PI/2,r=Math.min(w,h)*.34;entries.forEach(([name,val],i)=>{let end=start+Math.PI*2*val/total;ctx.beginPath();ctx.arc(w/2,h/2,r,start,end-.018);ctx.strokeStyle=COLORS[i%COLORS.length];ctx.lineWidth=Math.min(w,h)*.13;ctx.lineCap='round';ctx.stroke();start=end});ctx.fillStyle='#254a3e';ctx.textAlign='center';ctx.font='700 15px Manrope';ctx.fillText(money(total).replace(/\s/g,''),w/2,h/2+2);ctx.fillStyle='#92a19a';ctx.font='8px DM Sans';ctx.fillText(lang==='bn'?'মোট':'TOTAL',w/2,h/2+15);ctx.textAlign='left';if(legendEl)legendEl.innerHTML=entries.map(([k,v],i)=>`<div class="legend-row"><i class="legend-dot" style="background:${COLORS[i%COLORS.length]}"></i><span>${esc(categoryText(k))}</span><b>${number(v/total*100)}%</b></div>`).join('')}
