async function loadWhatIf(){if(!summary)return;if(!$('#scenario-controls').dataset.ready){renderScenarioControls();$('#scenario-controls').dataset.ready='1'}if(!activeGoalId){$('#scenario-status').textContent=tr('noEstimate');return}try{let result=await api(`/goals/${activeGoalId}/what-if`,{method:'POST',body:JSON.stringify({reductions})});let base=summary.planning;$('#scenario-status').textContent=statusText(result.planning_status);$('#scenario-reason').textContent=lang==='bn'?result.status_reason_bn:result.status_reason_en;$('#scenario-capacity').textContent=money(result.feasible_monthly_savings);$('#scenario-months').textContent=result.expected_completion_months===null?tr('noEstimate'):`${number(result.expected_completion_months)} ${tr('monthsLabel')}`;$('#scenario-total').textContent=`${tr('projectedSavings')||tr('cumulative')}: ${money(result.projected_savings)} · ${tr('remaining')}: ${money(result.remaining_gap_after_target)}`;drawScenario($('#scenario-chart'),base.feasible_monthly_savings,result.feasible_monthly_savings)}catch(e){$('#scenario-status').textContent=tr('noEstimate');notify(e.message,true)}}
function drawScenario(canvas,a,b){let{ctx,w,h}=canvasCtx(canvas);ctx.clearRect(0,0,w,h);let max=Math.max(a,b,1)*1.25,vals=[a,b],labels=[lang==='bn'?'এখন':'Current',lang==='bn'?'পরিস্থিতি':'Scenario'];ctx.font='9px DM Sans';vals.forEach((v,i)=>{let x=w*.27+i*w*.37,bw=Math.min(58,w*.19),bh=Math.max(3,(h-35)*v/max),y=h-25-bh;ctx.fillStyle=i?'#79b990':'#bad9c5';ctx.beginPath();ctx.roundRect(x-bw/2,y,bw,bh,6);ctx.fill();ctx.fillStyle='#436258';ctx.textAlign='center';ctx.font='700 9px DM Sans';ctx.fillText(money(v).replace(/\s/g,''),x,y-6);ctx.fillStyle='#8c9a94';ctx.font='8px DM Sans';ctx.fillText(labels[i],x,h-7)});ctx.textAlign='left'}
