function drawTrendBars(canvas,rows){if(!canvas)return;let{ctx,w,h}=canvasCtx(canvas),summaryNode=$('#spending-chart-summary'),tooltip=$('#spending-chart-tooltip');ctx.clearRect(0,0,w,h);let data=(rows||[]).slice(-12),values=data.map(r=>Math.max(0,Number(r.total)||0));if(!data.length){if(summaryNode)summaryNode.textContent=tr('noChartData');ctx.fillStyle='#899b93';ctx.textAlign='center';ctx.font='10px DM Sans';ctx.fillText(tr('noChartData'),w/2,h/2);canvas._barState=null;if(tooltip)tooltip.hidden=true;return}let rawMax=Math.max(...values,1),magnitude=10**Math.floor(Math.log10(rawMax/4||1)),step=Math.ceil((rawMax/4)/magnitude)*magnitude,max=step*4,pad={l:49,r:10,t:22,b:34},plotH=Math.max(1,h-pad.t-pad.b),plotW=Math.max(1,w-pad.l-pad.r),slot=plotW/data.length,bw=Math.min(30,slot*.62),compact=new Intl.NumberFormat(lang==='bn'?'bn-BD':'en-BD',{notation:'compact',maximumFractionDigits:1});ctx.font='8px DM Sans, sans-serif';ctx.lineWidth=1;for(let tick=0;tick<=4;tick++){let value=max-tick*step,y=pad.t+plotH*tick/4;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.strokeStyle=tick===4?'#dce7e1':'#edf2ef';ctx.stroke();ctx.fillStyle='#81928a';ctx.textAlign='right';ctx.textBaseline='middle';ctx.fillText(`৳${compact.format(value)}`,pad.l-7,y)}ctx.textBaseline='alphabetic';let bars=[];data.forEach((row,i)=>{let value=values[i],barH=value/max*plotH,x=pad.l+i*slot+(slot-bw)/2,y=pad.t+plotH-barH;ctx.fillStyle=i===data.length-1?'#328b6d':'#c5e1cf';ctx.beginPath();ctx.roundRect(x,y,bw,Math.max(2,barH),Math.min(5,bw/2));ctx.fill();bars.push({x,y,width:bw,height:barH,index:i});let date=new Date(`${row.month}-01T12:00:00`),label=new Intl.DateTimeFormat(lang==='bn'?'bn-BD':'en-US',{month:'short'}).format(date);if(date.getMonth()===0)label+=` '${String(date.getFullYear()).slice(-2)}`;let show=slot>=40||i%2===0||i===data.length-1;if(show){ctx.fillStyle=i===data.length-1?'#3b7460':'#899b93';ctx.textAlign='center';ctx.font='8px DM Sans, sans-serif';ctx.fillText(label,x+bw/2,h-8)}});let latest=values.at(-1),lastBar=bars.at(-1);if(slot>=38){ctx.fillStyle='#286b55';ctx.textAlign='center';ctx.font='700 8px DM Sans, sans-serif';ctx.fillText(`৳${compact.format(latest)}`,lastBar.x+bw/2,Math.max(11,lastBar.y-5))}canvas._barState={data,bars,pad,slot,width:w,height:h};canvas.setAttribute('aria-label',`${tr('monthlyActivity')}: ${data.length} ${tr('monthsLabel')}`);if(summaryNode)summaryNode.textContent=`${tr('chartRange')} ${data[0].month}–${data.at(-1).month}. ${tr('chartLatest')} ${money(latest)}.`;if(!canvas.dataset.tooltipReady){canvas.dataset.tooltipReady='1';canvas.addEventListener('pointermove',event=>{let state=canvas._barState,wrap=canvas.closest('.chart-canvas-wrap'),tip=wrap?.querySelector('.chart-tooltip');if(!state||!tip)return;let rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,index=Math.floor((x-state.pad.l)/state.slot);if(index<0||index>=state.data.length){tip.hidden=true;return}let row=state.data[index],bar=state.bars[index];tip.textContent=`${row.month} · ${money(row.total)} · ${number(row.transactions||0)} ${tr('transactionsWord')}`;tip.hidden=false;tip.style.left=`${Math.max(4,Math.min(wrap.clientWidth-tip.offsetWidth-4,bar.x+bar.width/2-tip.offsetWidth/2))}px`;tip.style.top=`${Math.max(4,bar.y-35)}px`});canvas.addEventListener('pointerleave',()=>{let tip=canvas.closest('.chart-canvas-wrap')?.querySelector('.chart-tooltip');if(tip)tip.hidden=true});canvas.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let state=canvas._barState,wrap=canvas.closest('.chart-canvas-wrap'),tip=wrap?.querySelector('.chart-tooltip');if(!state||!tip)return;let i=Number(canvas.dataset.activeBar||0);i=event.key==='Home'?0:event.key==='End'?state.data.length-1:Math.max(0,Math.min(state.data.length-1,i+(event.key==='ArrowRight'?1:-1)));canvas.dataset.activeBar=String(i);let row=state.data[i],bar=state.bars[i];tip.textContent=`${row.month} · ${money(row.total)} · ${number(row.transactions||0)} ${tr('transactionsWord')}`;tip.hidden=false;tip.style.left=`${Math.max(4,Math.min(wrap.clientWidth-tip.offsetWidth-4,bar.x+bar.width/2-tip.offsetWidth/2))}px`;tip.style.top=`${Math.max(4,bar.y-35)}px`})}}
