    let c=p.control||{},t=p.treatment||{},change=Number(p.goal_feasibility_change_percentage_points)||0,bn=lang==='bn';
    $('#impact-title').textContent=bn?'ছয় মাসের লক্ষ্য-সক্ষমতার সিমুলেশন':'Six-month customer outcome simulation';
    $('#impact-subtitle').textContent=bn?'নিরাপত্তা বাফার রেখে একটি উদাহরণমূলক খরচের পরিস্থিতি।':'Reserve-aware goal feasibility under one illustrative spending scenario.';
